<?php use SwimlogStandalone\EventList as EL; ?>
<section class="calendar-panel workout-page" aria-labelledby="events-title"><div class="workout-page-heading"><h2 id="events-title">Events</h2><?php if(current_user_can('swimlog_manage_own_events')): ?><a class="control" href="/?edit_event=new">Add event</a><?php endif; ?></div>
<?php if(is_wp_error($eventList)): ?><p role="alert"><?php echo esc_html($eventList->get_error_message()); ?></p><?php else: ?>
<nav class="event-filters" aria-label="Event list filter"><?php foreach(array('upcoming'=>'Upcoming','past'=>'Past','all'=>'All')as$key=>$label): ?><a class="control" <?php if($key===$eventList['view'])echo 'aria-current="page"'; ?> href="<?php echo esc_url(EL::url($key)); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></nav>
<p><?php echo esc_html($eventList['total']); ?> events · Page <?php echo esc_html($eventList['page'].' of '.$eventList['pages']); ?></p>
<?php if(!$eventList['items']): ?><p>No events in this view.</p><?php endif; ?>
<div class="event-list"><?php foreach($eventList['items']as$event): ?><article class="event-list-card"><h3><a data-event-id="<?php echo esc_attr($event['id']); ?>" aria-haspopup="dialog" aria-expanded="false" href="<?php echo esc_url(EL::url($eventList['view'],$eventList['page']).'&event='.$event['id']); ?>"><?php echo esc_html($event['title']); ?></a></h3><dl class="workout-metrics"><?php foreach($event['summary']as$label=>$value): ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($value); ?></dd></div><?php endforeach; ?><?php if($event['manage']&&$event['result']['time']!==''): ?><div><dt>Race time</dt><dd><?php echo esc_html($event['result']['time']); ?></dd></div><?php endif; ?></dl></article><?php endforeach; ?></div>
<nav class="event-filters" aria-label="Event list pages"><?php if($eventList['page']>1): ?><a class="control" href="<?php echo esc_url(EL::url($eventList['view'],$eventList['page']-1)); ?>">Previous page</a><?php endif; ?><?php if($eventList['page']<$eventList['pages']): ?><a class="control" href="<?php echo esc_url(EL::url($eventList['view'],$eventList['page']+1)); ?>">Next page</a><?php endif; ?></nav>
<?php endif; ?></section>
